import React, { useState, useEffect } from 'react';
import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  TouchableOpacity,
  Image,
  Alert,
  Modal,
  Animated,
  Dimensions,
  SafeAreaView,
} from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { useApp } from '../context/AppContext';

const { width, height } = Dimensions.get('window');

// Character data
const CHARACTERS = {
  common: [
    { id: 'c1', name: 'Fitness Rookie', rarity: 'common', image: '🏃‍♂️', stats: { strength: 10, endurance: 8, motivation: 12 } },
    { id: 'c2', name: 'Gym Rat', rarity: 'common', image: '💪', stats: { strength: 12, endurance: 10, motivation: 8 } },
    { id: 'c3', name: 'Cardio Queen', rarity: 'common', image: '🏃‍♀️', stats: { strength: 8, endurance: 15, motivation: 10 } },
  ],
  rare: [
    { id: 'r1', name: 'Iron Warrior', rarity: 'rare', image: '⚔️', stats: { strength: 18, endurance: 15, motivation: 12 } },
    { id: 'r2', name: 'Endurance Master', rarity: 'rare', image: '🏋️‍♂️', stats: { strength: 15, endurance: 20, motivation: 15 } },
    { id: 'r3', name: 'Motivation Guru', rarity: 'rare', image: '🌟', stats: { strength: 12, endurance: 12, motivation: 25 } },
  ],
  epic: [
    { id: 'e1', name: 'Legendary Lifter', rarity: 'epic', image: '👑', stats: { strength: 25, endurance: 20, motivation: 18 } },
    { id: 'e2', name: 'Unstoppable Force', rarity: 'epic', image: '🔥', stats: { strength: 30, endurance: 25, motivation: 20 } },
  ],
  legendary: [
    { id: 'l1', name: 'Fitness Deity', rarity: 'legendary', image: '⚡', stats: { strength: 40, endurance: 35, motivation: 30 } },
    { id: 'l2', name: 'Ultimate Champion', rarity: 'legendary', image: '🏆', stats: { strength: 35, endurance: 40, motivation: 35 } },
  ],
};

const RARITY_WEIGHTS = {
  common: 60,
  rare: 30,
  epic: 8,
  legendary: 2,
};

const RARITY_COLORS = {
  common: '#8B8B8B',
  rare: '#4A90E2',
  epic: '#9B59B6',
  legendary: '#F39C12',
};

export const GachaScreen = ({ navigation }) => {
  const { userStats } = useApp();
  const [gems, setGems] = useState(userStats.gems || 0);
  const [isPulling, setIsPulling] = useState(false);
  const [pullResult, setPullResult] = useState(null);
  const [showResult, setShowResult] = useState(false);
  const [animation] = useState(new Animated.Value(0));

  const pullCharacter = () => {
    if (gems < 100) {
      Alert.alert('Not Enough Gems', 'You need 100 gems to pull a character!');
      return;
    }

    setIsPulling(true);
    setGems(gems - 100);

    // Animated pull effect
    Animated.sequence([
      Animated.timing(animation, {
        toValue: 1,
        duration: 1000,
        useNativeDriver: true,
      }),
      Animated.timing(animation, {
        toValue: 0,
        duration: 500,
        useNativeDriver: true,
      }),
    ]).start(() => {
      const result = performGachaPull();
      setPullResult(result);
      setShowResult(true);
      setIsPulling(false);
    });
  };

  const performGachaPull = () => {
    const random = Math.random() * 100;
    let cumulativeWeight = 0;
    let selectedRarity = 'common';

    for (const [rarity, weight] of Object.entries(RARITY_WEIGHTS)) {
      cumulativeWeight += weight;
      if (random <= cumulativeWeight) {
        selectedRarity = rarity;
        break;
      }
    }

    const charactersOfRarity = CHARACTERS[selectedRarity];
    const randomCharacter = charactersOfRarity[Math.floor(Math.random() * charactersOfRarity.length)];

    return {
      ...randomCharacter,
      isNew: !userStats.characters?.includes(randomCharacter.id),
    };
  };

  const confirmPullResult = () => {
    setShowResult(false);
    setPullResult(null);
    // Here you would update the user's character collection
    // This would be handled by the AppContext
  };

  return (
    <SafeAreaView style={styles.container}>
      <View style={styles.header}>
        <TouchableOpacity onPress={() => navigation.goBack()} style={styles.backButton}>
          <Ionicons name="arrow-back" size={24} color="#333" />
        </TouchableOpacity>
        <Text style={styles.headerTitle}>Character Gacha</Text>
        <View style={styles.gemDisplay}>
          <Ionicons name="diamond" size={20} color="#F39C12" />
          <Text style={styles.gemText}>{gems}</Text>
        </View>
      </View>

      <ScrollView style={styles.content}>
        <View style={styles.gachaSection}>
          <Text style={styles.sectionTitle}>Pull a Character</Text>
          <Text style={styles.sectionDescription}>
            Spend 100 gems to pull a random character. Each character provides unique bonuses to your workouts!
          </Text>

          <TouchableOpacity
            style={[styles.pullButton, isPulling && styles.pullButtonDisabled]}
            onPress={pullCharacter}
            disabled={isPulling || gems < 100}
          >
            <Animated.View
              style={[
                styles.pullButtonContent,
                {
                  transform: [
                    {
                      scale: animation.interpolate({
                        inputRange: [0, 1],
                        outputRange: [1, 1.2],
                      }),
                    },
                  ],
                },
              ]}
            >
              <Ionicons name="gift" size={32} color="#fff" />
              <Text style={styles.pullButtonText}>
                {isPulling ? 'Pulling...' : 'Pull Character (100 Gems)'}
              </Text>
            </Animated.View>
          </TouchableOpacity>

          <View style={styles.ratesSection}>
            <Text style={styles.ratesTitle}>Pull Rates:</Text>
            <View style={styles.rateItem}>
              <Text style={[styles.rarityText, { color: RARITY_COLORS.common }]}>Common: 60%</Text>
            </View>
            <View style={styles.rateItem}>
              <Text style={[styles.rarityText, { color: RARITY_COLORS.rare }]}>Rare: 30%</Text>
            </View>
            <View style={styles.rateItem}>
              <Text style={[styles.rarityText, { color: RARITY_COLORS.epic }]}>Epic: 8%</Text>
            </View>
            <View style={styles.rateItem}>
              <Text style={[styles.rarityText, { color: RARITY_COLORS.legendary }]}>Legendary: 2%</Text>
            </View>
          </View>
        </View>

        <View style={styles.collectionPreview}>
          <Text style={styles.sectionTitle}>Your Collection</Text>
          <Text style={styles.collectionCount}>
            {userStats.characters?.length || 0} / {Object.values(CHARACTERS).flat().length} Characters
          </Text>
          <TouchableOpacity
            style={styles.viewCollectionButton}
            onPress={() => navigation.navigate('CharacterCollection')}
          >
            <Text style={styles.viewCollectionButtonText}>View Full Collection</Text>
            <Ionicons name="chevron-forward" size={20} color="#007AFF" />
          </TouchableOpacity>
        </View>
      </ScrollView>

      <Modal visible={showResult} transparent animationType="fade">
        <View style={styles.modalOverlay}>
          <View style={styles.resultModal}>
            <Text style={styles.resultTitle}>
              {pullResult?.isNew ? '🎉 New Character!' : 'Character Obtained!'}
            </Text>
            <View style={[styles.characterCard, { borderColor: RARITY_COLORS[pullResult?.rarity] }]}>
              <Text style={styles.characterImage}>{pullResult?.image}</Text>
              <Text style={styles.characterName}>{pullResult?.name}</Text>
              <Text style={[styles.characterRarity, { color: RARITY_COLORS[pullResult?.rarity] }]}>
                {pullResult?.rarity.toUpperCase()}
              </Text>
              <View style={styles.characterStats}>
                <Text style={styles.statText}>Strength: {pullResult?.stats.strength}</Text>
                <Text style={styles.statText}>Endurance: {pullResult?.stats.endurance}</Text>
                <Text style={styles.statText}>Motivation: {pullResult?.stats.motivation}</Text>
              </View>
            </View>
            <TouchableOpacity style={styles.confirmButton} onPress={confirmPullResult}>
              <Text style={styles.confirmButtonText}>Add to Collection</Text>
            </TouchableOpacity>
          </View>
        </View>
      </Modal>
    </SafeAreaView>
  );
};

export const CharacterCollectionScreen = ({ navigation }) => {
  const { userStats } = useApp();
  const [selectedCharacter, setSelectedCharacter] = useState(null);
  const [showCharacterModal, setShowCharacterModal] = useState(false);

  const userCharacters = userStats.characters || [];
  const allCharacters = Object.values(CHARACTERS).flat();

  const getUserCharacter = (characterId) => {
    return allCharacters.find(char => char.id === characterId);
  };

  const openCharacterDetails = (character) => {
    setSelectedCharacter(character);
    setShowCharacterModal(true);
  };

  return (
    <SafeAreaView style={styles.container}>
      <View style={styles.header}>
        <TouchableOpacity onPress={() => navigation.goBack()} style={styles.backButton}>
          <Ionicons name="arrow-back" size={24} color="#333" />
        </TouchableOpacity>
        <Text style={styles.headerTitle}>Character Collection</Text>
        <View />
      </View>

      <ScrollView style={styles.content}>
        <View style={styles.collectionStats}>
          <Text style={styles.collectionTitle}>Your Collection</Text>
          <Text style={styles.collectionProgress}>
            {userCharacters.length} / {allCharacters.length} Characters
          </Text>
          <View style={styles.progressBar}>
            <View
              style={[
                styles.progressFill,
                { width: `${(userCharacters.length / allCharacters.length) * 100}%` },
              ]}
            />
          </View>
        </View>

        <View style={styles.charactersGrid}>
          {allCharacters.map((character) => {
            const isOwned = userCharacters.includes(character.id);
            return (
              <TouchableOpacity
                key={character.id}
                style={[
                  styles.characterCard,
                  { borderColor: RARITY_COLORS[character.rarity] },
                  !isOwned && styles.characterCardLocked,
                ]}
                onPress={() => isOwned && openCharacterDetails(character)}
                disabled={!isOwned}
              >
                <Text style={[styles.characterImage, !isOwned && styles.characterImageLocked]}>
                  {isOwned ? character.image : '🔒'}
                </Text>
                <Text style={[styles.characterName, !isOwned && styles.characterNameLocked]}>
                  {isOwned ? character.name : '???'}
                </Text>
                <Text
                  style={[
                    styles.characterRarity,
                    { color: RARITY_COLORS[character.rarity] },
                    !isOwned && styles.characterRarityLocked,
                  ]}
                >
                  {isOwned ? character.rarity.toUpperCase() : 'LOCKED'}
                </Text>
              </TouchableOpacity>
            );
          })}
        </View>
      </ScrollView>

      <Modal visible={showCharacterModal} transparent animationType="slide">
        <View style={styles.modalOverlay}>
          <View style={styles.characterModal}>
            <View style={styles.modalHeader}>
              <Text style={styles.modalTitle}>Character Details</Text>
              <TouchableOpacity onPress={() => setShowCharacterModal(false)}>
                <Ionicons name="close" size={24} color="#333" />
              </TouchableOpacity>
            </View>
            {selectedCharacter && (
              <View style={styles.characterDetails}>
                <Text style={styles.characterImageLarge}>{selectedCharacter.image}</Text>
                <Text style={styles.characterNameLarge}>{selectedCharacter.name}</Text>
                <Text
                  style={[
                    styles.characterRarityLarge,
                    { color: RARITY_COLORS[selectedCharacter.rarity] },
                  ]}
                >
                  {selectedCharacter.rarity.toUpperCase()}
                </Text>
                <View style={styles.statsContainer}>
                  <Text style={styles.statsTitle}>Stats:</Text>
                  <View style={styles.statRow}>
                    <Text style={styles.statLabel}>Strength:</Text>
                    <Text style={styles.statValue}>{selectedCharacter.stats.strength}</Text>
                  </View>
                  <View style={styles.statRow}>
                    <Text style={styles.statLabel}>Endurance:</Text>
                    <Text style={styles.statValue}>{selectedCharacter.stats.endurance}</Text>
                  </View>
                  <View style={styles.statRow}>
                    <Text style={styles.statLabel}>Motivation:</Text>
                    <Text style={styles.statValue}>{selectedCharacter.stats.motivation}</Text>
                  </View>
                </View>
                <Text style={styles.characterDescription}>
                  This character provides bonuses to your workouts based on their stats.
                </Text>
              </View>
            )}
          </View>
        </View>
      </Modal>
    </SafeAreaView>
  );
};

